<?php
namespace App\Models;
use App\Enums\ExaminationStatus; use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['title','description','opens_at','closes_at','duration_minutes','attempt_limit','passing_score','randomize_questions','randomize_choices','one_question_at_a_time','allow_back_navigation','auto_submit','access_code'])]
class Examination extends Model { protected function casts():array{return ['status'=>ExaminationStatus::class,'opens_at'=>'datetime','closes_at'=>'datetime','duration_minutes'=>'integer','attempt_limit'=>'integer','passing_score'=>'decimal:2','randomize_questions'=>'boolean','randomize_choices'=>'boolean','one_question_at_a_time'=>'boolean','allow_back_navigation'=>'boolean','auto_submit'=>'boolean'];} public function classSubject():BelongsTo{return $this->belongsTo(ClassSubject::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function examinationQuestions():HasMany{return $this->hasMany(ExaminationQuestion::class)->orderBy('position');} public function questions():BelongsToMany{return $this->belongsToMany(Question::class,'examination_questions')->withPivot(['position','points'])->orderByPivot('position');} public function isActive(?\DateTimeInterface $at=null):bool{$at=$at??now();return $this->status===ExaminationStatus::Published && ($this->opens_at===null||$this->opens_at<=$at) && ($this->closes_at===null||$this->closes_at>$at);} }
